<?php
declare(strict_types=1); require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/functions.php'; require_login(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';$id=filter_input(INPUT_POST,'participant_id',FILTER_VALIDATE_INT);$first=trim((string)($_POST['first_name']??''));$last=trim((string)($_POST['last_name']??''));$email=trim((string)($_POST['email']??''));$phone=trim((string)($_POST['phone']??''));$address=trim((string)($_POST['address']??''));try{if($a==='save'){if($first===''||$last===''||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)))throw new InvalidArgumentException('First name, last name, and a valid email are required.');if($id){$s=$pdo->prepare('UPDATE participants SET first_name=?,last_name=?,email=?,phone=?,address=? WHERE participant_id=?');$s->execute([$first,$last,$email,$phone,$address,$id]);flash('success','Participant updated successfully.');}else{$s=$pdo->prepare('INSERT INTO participants(first_name,last_name,email,phone,address) VALUES(?,?,?,?,?)');$s->execute([$first,$last,$email,$phone,$address]);flash('success','Participant added successfully.');}}elseif($a==='delete'&&$id){$s=$pdo->prepare('DELETE FROM participants WHERE participant_id=?');$s->execute([$id]);flash('success','Participant deleted successfully.');}redirect('/event_shit/participants/participants.php');}catch(InvalidArgumentException|PDOException $x){$error=$x instanceof InvalidArgumentException?$x->getMessage():'Unable to complete the participant operation.';}}$q=trim((string)($_GET['search']??''));$s=$pdo->prepare("SELECT * FROM participants WHERE first_name LIKE ? OR last_name LIKE ? OR email LIKE ? ORDER BY last_name,first_name");$t="%$q%";$s->execute([$t,$t,$t]);$rows=$s->fetchAll();$pageTitle='Participants';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';
?><main class="col-md-9 col-lg-10 p-4"><?php require __DIR__.'/../includes/alerts.php';if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="d-flex justify-content-between mb-4"><h1 class="h3">Participants</h1><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#edit">+ Add participant</button></div><form class="row g-2 mb-3"><div class="col-sm-6"><input class="form-control" name="search" value="<?=e($q)?>" placeholder="Search participants"></div><div class="col-auto"><button class="btn btn-outline-secondary">Search</button></div></form><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>ID</th><th>Full name</th><th>Email</th><th>Phone</th><th>Address</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['participant_id']?></td><td><?=e($r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['address'])?></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#edit" data-id="<?=$r['participant_id']?>" data-first="<?=e($r['first_name'])?>" data-last="<?=e($r['last_name'])?>" data-email="<?=e($r['email'])?>" data-phone="<?=e($r['phone'])?>" data-address="<?=e($r['address'])?>">Edit</button><button class="btn btn-sm btn-outline-danger" data-bs-toggle="modal" data-bs-target="#delete" data-id="<?=$r['participant_id']?>" data-name="<?=e($r['first_name'].' '.$r['last_name'])?>">Delete</button></td></tr><?php endforeach;?></tbody></table></div></div></main><div class="modal fade" id="edit"><div class="modal-dialog"><form class="modal-content" method="post"><div class="modal-header"><h2 class="modal-title fs-5">Participant</h2><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="participant_id" id="participant_id"><?php foreach(['first_name'=>'First name','last_name'=>'Last name','email'=>'Email','phone'=>'Phone','address'=>'Address'] as $f=>$l):?><label class="form-label"><?=$l?></label><input class="form-control mb-2" name="<?=$f?>" id="<?=$f?>" type="<?=$f==='email'?'email':'text'?>" <?=$f==='first_name'||$f==='last_name'?'required':''?>><?php endforeach;?></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div><div class="modal fade" id="delete"><div class="modal-dialog"><form class="modal-content" method="post"><div class="modal-header"><h2 class="modal-title fs-5">Confirm delete</h2><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body">Delete <strong id="dn"></strong>?<input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="participant_id" id="di"></div><div class="modal-footer"><button class="btn btn-secondary" data-bs-dismiss="modal" type="button">Cancel</button><button class="btn btn-danger">Delete</button></div></form></div></div><script>edit.addEventListener('show.bs.modal',e=>{let b=e.relatedTarget;['id','first','last','email','phone','address'].forEach(k=>document.getElementById(k==='id'?'participant_id':k).value=b.dataset[k]||'')});delete.addEventListener('show.bs.modal',e=>{let b=e.relatedTarget;di.value=b.dataset.id;dn.textContent=b.dataset.name});</script><?php require __DIR__.'/../includes/footer.php';?>
